insert into public.units(subject_id,code,name,position,source_page,source_text) values ((select id from public.subjects where code='CHEMISTRY'),'C2','Inorganic Chemistry',2,8,'Chemistry of Non-metals: Atomic, molecular, and nascent hydrogen, isotopes of hydrogen, heavy water, types of oxides, preparation, structure and test of ozone. Ozone layer depletion, chemical properties of ammonia, phosphine and nitric acid, general characteristics, preparation, chemical properties and test of chlorine, bromine and iodine, preparation and chemical properties of HCl, HBr and HI, allotropes of carbon, chemical properties of carbon monoxide, chemical properties of hydrogen sulphide, sulphur dioxide, sulphuric acid. Chemistry of Metals: Metallurgical principles (hydrometallurgy, pyrometallurgy, electrometallurgy, ores, gangue, flux, slag, concentration, calcination, roasting, smelting, bessemerization, aluminothermite, electrochemical reduction, poling, electro-refinement, zone refining), general characteristics of alkali and alkaline earth metals and chemical properties of sodium, sodium hydroxide, and sodium carbonate, general characteristics of transition metals (3d series), shape of complex ions ( tetrahedral, square planar and octahedral), crystal field theory of octahedral complex, occurrence, extraction and chemical properties of copper, zinc, mercury, silver and iron from their ores, chemical properties of blue vitriol, white vitriol, calomel, corrosive sublimate, manufacture of steel by basic oxygen method and open hearth process, corrosion of iron. Bio-inorganic Chemistry: Concept of micro and macro nutrients, biological importance of ions of sodium, potassium, magnesium, zinc, copper, cobalt, nickel, iron, chromium and calcium, sodium-potassium and sodium-glucose pump, toxicity due to iron, arsenic, mercury, lead and cadmium.') on conflict(subject_id,code) do update set name=excluded.name,source_page=excluded.source_page,source_text=excluded.source_text;
