insert into public.units(subject_id,code,name,position,source_page,source_text) values ((select id from public.subjects where code='CHEMISTRY'),'C3','Organic Chemistry',3,9,'General Organic Chemistry: Tetra-covalency, catenation of carbon, classification of organic compounds, alkyl and aryl groups, functional groups, homologous series, IUPAC name of aliphatic compounds, isomerism of organic compounds, heterolytic and homolytic bond fission, electrophile, nucleophile, carbocation, carbanion, free radicals, inductive effect, resonance effect. Hydrocarbons: Concept of cracking, pyrolysis, reforming, quality of gasoline, octane number, cetane number and gasoline additive. Isomerism, IUPAC name, general methods of preparation of alkane, alkene and alkyne, chemical properties of ethane, addition reaction of alkene, addition reaction and acidity of alkyne. Aromatic Hydrocarbons: Aromaticity of aromatic hydrocarbons, resonance, preparation and chemical properties of benzene. Haloalkanes and Haloarenes: Nomenclature, isomerism, classification, preparation and properties of monohaloalkanes, concept of SN1 and SN2 mechanisms, preparation and chemical properties of chloroform and chlorobenzene. Alcohols and Phenols: Nomenclature, isomerism, classification, preparation and chemical properties of monohydric alcohols, industrial manufacture of alcohols by oxo-process, hydroboration-oxidation of ethene and fermentation of sugar, types of ethanol (absolute, power, methylated, rectified spirit, alcoholic beverages), preparation and properties of phenol. Ethers: Nomenclature, classification, isomerism, Williamson’s synthesis of ethers, chemical properties of diethyl ether. Aldehydes and Ketones: Nomenclature, isomerism, preparation and chemical properties of aliphatic carbonyl compounds, preparation and properties of benzaldehyde. Carboxylic Acid and its Derivatives: Nomenclature, isomerism, preparation and chemical properties of monocarboxylic acids, preparation, properties and relative reactivity of acid halide, acid anhydride, amides and esters. Nitro-compounds: Nomenclature, isomerism, preparation and chemical properties of nitroalkanes and nitrobenzene. Amine: Nomenclature, classification, isomerism of amines, preparation of primary amines, basicity of amines, separation of primary, secondary and tertiary amines by Hoffmann’s method, preparation and chemical properties of aniline. Organometallic Compounds: General formula and example of organo-lithium, organocopper and organocadmium compounds, metal carbon bonding, preparation and chemical properties of Grignard’s reagent.') on conflict(subject_id,code) do update set name=excluded.name,source_page=excluded.source_page,source_text=excluded.source_text;
