insert into public.units(subject_id,code,name,position,source_page,source_text) values ((select id from public.subjects where code='CHEMISTRY'),'C4','Applied Chemistry',4,9,'Fundamentals of Applied Chemistry and Manufacturing Processes: Chemical industry (importance and production stages), economical production and chemical plant management (cost, cash flow, operation, and design), continuous and batch processing, environmental effect of chemical industry with control measures, cement, paper and pulp, principle of modern manufacture of nitric acid (Ostwald’s process), ammonia (Haber’s process), sulphuric acid (Contact process), caustic soda (Diaphragm cell) , sodium carbonate (Ammonia soda or Solvay process), urea (Ammonium carbamate process). Applications of Non-metals, Metals and Compounds: Hydrogen and its isotopes, oxygen, ozone, heavy water, hydrogen peroxide, nitrogen, ammonia, nitric acid, sulphur, hydrogen sulphide, sulphur dioxide, sulphuric acid, hypo, halogen, halogen acids, carbon, carbon monoxide, phosphorous, phosphine, sodium, caustic soda, washing soda, baking soda, quick lime, slaked lime bleaching powder, plaster of Paris, magnesia, epsom salt, gypsum salt, copper, blue vitriol, black and red oxide of copper, zinc, white vitriol, mercury, calomel, corrosive sublimate, iron, silver chloride and silver nitrate. Alkane, alkene, alkyne, aromatic hydrocarbons, chloroform, alcohol, phenol, aldehydes and ketones, ethers, haloarene, carboxylic acid and its derivatives, nitro-compounds, amines, nitrocompounds, formalin, chloropicrin, chloretone, Grignard’s reagent. Chemistry in Service to Mankind: Polymer, dyes, drugs, pesticides, fertilizer, applications of colloid, osmotic pressure, buffer in daily life, medical and industrial applications of radioisotopes.') on conflict(subject_id,code) do update set name=excluded.name,source_page=excluded.source_page,source_text=excluded.source_text;
