insert into public.units(subject_id,code,name,position,source_page,source_text) values ((select id from public.subjects where code='CHEMISTRY'),'C5','Analytical Chemistry',5,10,'Chemical Tests: Tests of acid and basic radicals, tests of unsaturation and functional groups of organic compounds, distinction tests of organic compounds, hetero-element detection by Lassaigne’s test, biomolecule tests (fat, protein and carbohydrate). Separation Techniques: Filtration, sublimation, evaporation, precipitation, simple and fractional crystallization, simple fractional and vacuum distillation, paper chromatography, atmolysis. Types of Titration: Concept of acid-base, redox (permanganometric, iodometric and iodimetric) and complexometric titration, selection of indicators in acid base titration.') on conflict(subject_id,code) do update set name=excluded.name,source_page=excluded.source_page,source_text=excluded.source_text;
