insert into public.units(subject_id,code,name,position,source_page,source_text) values ((select id from public.subjects where code='PHYSICS'),'P1','Mechanics',1,10,'Physical quantities, vectors and scalars: Concept and application related to precision, accuracy, significant figures and dimensional analysis; concept, laws and calculations related to vectors and scalars. Kinematics: Concepts, calculations and graphical treatment of physical quantities of linear and projectile motions in presence as well as absence of resistive force. Dynamics: Concepts, laws (including Newton''s laws and equilibrium conditions) and application of physical quantities (force, impulse, momentum, torque, work, energy and power) related to linear a motions, collisions and solid friction. Rotational dynamics: Concepts, laws and application of physical quantities (moment of inertia (rigid uniform rod only), radius of gyration, torque, work, energy and power) related to rotational motion. Fluid statics and dynamics: Concepts (pressure, surface tension and energy and capillary action) and laws/principles (Newton, Stokes, Poiseuille, Bernoulli) related to fluids, and their applications. Circular and Periodic motion: Concepts, laws and application of physical quantities (displacement, velocity, acceleration, centripetal force) related to motion in horizontal and vertical circle; concepts, calculations, graphical treatment and application of physical quantities (period, frequency, displacement, amplitude, velocity, acceleration, restoring force, energy) of simple harmonic motion; concept of forced oscillations. Gravity: Definitions, laws, calculations, graphical treatment and application of concepts related to gravitation (force, acceleration, field strength, energy and potential. Elasticity: Concepts related to elasticity of matter (strain, stress, modii of elasticity, Poisson ratio and energy density), their calculations and applications.') on conflict(subject_id,code) do update set name=excluded.name,source_page=excluded.source_page,source_text=excluded.source_text;
insert into public.topics(unit_id,name,position,source_text,source_page) values ((select u.id from public.units u join public.subjects s on s.id=u.subject_id where u.code='P1' and s.code='PHYSICS'),'Physical quantities, vectors and scalars',1,'Physical quantities, vectors and scalars: Concept and application related to precision, accuracy, significant figures and dimensional analysis; concept, laws and calculations related to vectors and scalars.',10) on conflict(unit_id,name) do update set position=excluded.position,source_text=excluded.source_text,source_page=excluded.source_page;
