insert into public.units(subject_id,code,name,position,source_page,source_text) values ((select id from public.subjects where code='PHYSICS'),'P2','Heat and thermodynamics',2,11,'Thermal energy, heat, temperature, heat flow and thermometers: Concept of thermal energy, heat and temperature; modes and laws (zeroth law and Stefan Bolzmann) of heat flow; working principle, advantages and limitations of different types of thermometers (liquid in glass, resistance thermometer and radiation thermometer). Thermal expansion: Concept of linear, cubical, superficial, real and apparent expansions, their calculation and applications. Quantity of heat: Concept of heat capacity, specific heat capacity, latent heats and triple point, and their calculations and applications. Ideal gas: Molecular properties of ideal gas and calculations related to pressure, volume, temperature, rms speed, energy. First law of thermodynamics: Concept and calculations related to thermodynamic system and processes (adiabatic, isothermal, isochoric and isobaric); Second law of thermodynamics: Second law and its application in relation to internal combustion heat engines and refrigerator, concept of entropy.') on conflict(subject_id,code) do update set name=excluded.name,source_page=excluded.source_page,source_text=excluded.source_text;
insert into public.topics(unit_id,name,position,source_text,source_page) values ((select u.id from public.units u join public.subjects s on s.id=u.subject_id where u.code='P2' and s.code='PHYSICS'),'Thermal energy, heat, temperature, heat flow and thermometers',1,'Thermal energy, heat, temperature, heat flow and thermometers: Concept of thermal energy, heat and temperature; modes and laws (zeroth law and Stefan Bolzmann) of heat flow; working principle, advantages and limitations of different types of thermometers (liquid in glass, resistance thermometer and radiation thermometer).',11) on conflict(unit_id,name) do update set position=excluded.position,source_text=excluded.source_text,source_page=excluded.source_page;
