insert into public.units(subject_id,code,name,position,source_page,source_text) values ((select id from public.subjects where code='PHYSICS'),'P3','Waves and optics',3,11,'Wave motion: Concept, calculation related to progressive waves, velocity of sound in solid, liquid and gas and factors affecting the velocity. Stationary waves: Concept of stationary waves, calculations and applications in relation to velocity, harmonics and overtones in pipes and strings. Acoustic phenomena: Pressure amplitude and characteristics of waves(intensity, loudness, quality and pitch), concept, calculations and applications of Doppler effect. Reflection, refraction and dispersion: Reflection at curve mirror, refraction at plane surfaces and in lens; concept, calculations and application of dispersion (chromatic aberration, and achromatism);. Interference: Concept, conditions and applications of interference; calculations and applications related to Young''s double slit experiment. Diffraction and polarization: Concept and conditions of diffraction, diffraction at a single slit and diffraction grating, resolving power of optical instruments; concept of polarization and Brewster''s law.') on conflict(subject_id,code) do update set name=excluded.name,source_page=excluded.source_page,source_text=excluded.source_text;
