insert into public.units(subject_id,code,name,position,source_page,source_text) values ((select id from public.subjects where code='PHYSICS'),'P4','Current electricity and magnetism',4,11,'Electrical quantities: Concepts, laws (Ohm''s and Joule''s) and calculations related to electrical quantities (resistances, emf, pd, energy, power). Electrical circuits: Concepts, laws (including Kirchhoff''s laws) and their application related to resistors in different types of combinations, concept and calculations related to Wheatstone Bridge, meter bridge, potentiometer and galvanometer as ammeter and voltmeter. Thermoelectric effect: Concept and application of Seebeck and Peltier effects, concepts and calculations related to thermocouple. Alternating currents: Concept and calculation related to peak and rms values of AC, impedance, power, Q-factor and phase in LRC circuits; rectification using diode bridge. Magnetic properties of materials: Properties (domains, relative permeability, susceptibility and hysteresis) of Dia, para and ferromagnetic materials. Magnetic field: Nature of B-field around straight current carrying conductor, circular coil and long solenoid; concept, calculations and application of effect of uniform B-field on a moving charge and current carrying conductor/ coil, Hall effect. Electromagnetic induction: Principle and calculation related to Faraday’s law and Lenz’s law and their applications in connection to A.C. generator, transformer and formation of eddy current, concept of inductance (self and mutual) and energy stored in an inductor.') on conflict(subject_id,code) do update set name=excluded.name,source_page=excluded.source_page,source_text=excluded.source_text;
