insert into public.units(subject_id,code,name,position,source_page,source_text) values ((select id from public.subjects where code='PHYSICS'),'P5','Electrostatics and capacitors',5,12,'Electric charge and electric field: Electric field due to point charges, concept of electrostatic induction, Coulomb’s law and its applications. Electric field strength, potential and potential energy: Concepts, calculation, graphical analysis, law (Gauss) and related applications. Capacitors: Principle of capacitor; concept, calculation and application of parallel plate capacitor, combinations of capacitors and energy density, effect of dielectric.') on conflict(subject_id,code) do update set name=excluded.name,source_page=excluded.source_page,source_text=excluded.source_text;
