insert into public.units(subject_id,code,name,position,source_page,source_text) values ((select id from public.subjects where code='PHYSICS'),'P6','Modern physics',6,12,'Nuclear physics: Nucleus and its properties (charge, size, mass, density); concept and calculations of mass defect, binding energy per nucleon, Einstein’s mass- energy relation; nuclear fusion and fission. Electron: Concept, calculations and applications related to the motion of electron in an electric and magnetic field, Millikan’s oil drop experiment and J.J. Thomson’s experiment. Photon- Concept, laws and calculations related to photon and photo-electric effect. Wave particle duality: Concepts and calculations of Bohr’s theory of hydrogen atom including spectral series, energy levels, De-Broglie wave and uncertainty principle, properties, uses and production of X rays and their calculations; Bragg’s law and applications. Radioactivity: Concept, laws and units of radioactivity, properties of alpha, beta and gamma rays, concept, calculation and applications of half-life, mean life and their relations, carbon dating; medical use of nuclear radiations and health hazard. Solid and semiconductor device: Concept of energy band in solids (metal, semiconductor and insulator); intrinsic and extrinsic semiconductor, p-n diode, biasing of diode, p-n diode as a rectifier; logic gates (AND, OR, NOT, NOR, NAND). Particle physics and recent trends: Concept of particle, antiparticle, leptons and quarks, Higgs boson, nanotechnology, big bang theory, Hubble law.') on conflict(subject_id,code) do update set name=excluded.name,source_page=excluded.source_page,source_text=excluded.source_text;
